{
  "units": [
    {
      "quote_ref": "F000",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "Except as provided in paragraph (b), the driver of a commercial motor vehicle specified in paragraphs (a)(1) through (6) must not cross a railroad track or tracks at grade unless he or she first stops the commercial motor vehicle within 50 feet of, and not closer than 15 feet to, the tracks, thereafter listens and looks in each direction along the tracks for an approaching train, and ascertains that no train is approaching."
    },
    {
      "quote_ref": "F000",
      "scope_refs": [],
      "kind": "permission",
      "meaning": "When it is safe to do so, the driver of a specified commercial motor vehicle may drive across the tracks in a gear that permits the vehicle to complete the crossing without a change of gears."
    },
    {
      "quote_ref": "F000",
      "scope_refs": [],
      "kind": "prohibition",
      "meaning": "The driver of a specified commercial motor vehicle must not shift gears while crossing the railroad tracks."
    },
    {
      "quote_ref": "F001",
      "scope_refs": ["F000"],
      "kind": "condition",
      "meaning": "The grade crossing stopping, listening, looking, and crossing rules apply to every bus transporting passengers."
    },
    {
      "quote_ref": "F002",
      "scope_refs": ["F000"],
      "kind": "condition",
      "meaning": "The grade crossing stopping, listening, looking, and crossing rules apply to every commercial motor vehicle transporting any quantity of a Division 2.3 chlorine."
    },
    {
      "quote_ref": "F003:F021",
      "scope_refs": ["F000"],
      "kind": "condition",
      "meaning": "The grade crossing stopping, listening, looking, and crossing rules apply to every commercial motor vehicle that, in accordance with the regulations of the Department of Transportation, is required to be marked or placarded with any of the following classifications: Division 1.1; Division 1.2 or Division 1.3; Division 2.3 Poison gas; Division 4.3; Class 7; Class 3 Flammable; Division 5.1; Division 2.2; Division 2.3 Chlorine; Division 6.1 Poison; Division 2.2 Oxygen; Division 2.1; Class 3 Combustible liquid; Division 4.1; Division 5.1; Division 5.2; Class 8; or Division 1.4."
    },
    {
      "quote_ref": "F022",
      "scope_refs": ["F000"],
      "kind": "condition",
      "meaning": "The grade crossing stopping, listening, looking, and crossing rules apply to every cargo tank motor vehicle, whether loaded or empty, used for the transportation of any hazardous material as defined in the Hazardous Materials Regulations of the Department of Transportation (49 CFR parts 107 through 180)."
    },
    {
      "quote_ref": "F023",
      "scope_refs": ["F000"],
      "kind": "condition",
      "meaning": "The grade crossing stopping, listening, looking, and crossing rules apply to every cargo tank motor vehicle transporting a commodity which at the time of loading has a temperature above its flashpoint as determined by 49 CFR 173.120."
    },
    {
      "quote_ref": "F024",
      "scope_refs": ["F000"],
      "kind": "condition",
      "meaning": "The grade crossing stopping, listening, looking, and crossing rules apply to every cargo tank motor vehicle, whether loaded or empty, transporting any commodity under exemption in accordance with the provisions of subpart B of part 107 of title 49."
    },
    {
      "quote_ref": "F026",
      "scope_refs": ["F025"],
      "kind": "exception",
      "meaning": "A stop need not be made at a streetcar crossing, or at railroad tracks used exclusively for industrial switching purposes, within a business district as defined in 49 CFR 390.5."
    },
    {
      "quote_ref": "F027",
      "scope_refs": ["F025"],
      "kind": "exception",
      "meaning": "A stop need not be made at a railroad grade crossing when a police officer or crossing flagman directs traffic to proceed."
    },
    {
      "quote_ref": "F028",
      "scope_refs": ["F025"],
      "kind": "exception",
      "meaning": "A stop need not be made at a railroad grade crossing controlled by a functioning highway traffic signal transmitting a green indication which, under local law, permits the commercial motor vehicle to proceed across the railroad tracks without slowing or stopping."
    },
    {
      "quote_ref": "F029",
      "scope_refs": ["F025"],
      "kind": "exception",
      "meaning": "A stop need not be made at an abandoned railroad grade crossing that is marked with a sign indicating that the rail line is abandoned."
    },
    {
      "quote_ref": "F030",
      "scope_refs": ["F025"],
      "kind": "exception",
      "meaning": "A stop need not be made at an industrial or spur line railroad grade crossing marked with a sign reading 'Exempt.'"
    },
    {
      "quote_ref": "F030",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "'Exempt' signs at industrial or spur line railroad grade crossings shall be erected only by or with the consent of the appropriate State or local authority."
    }
  ]
}
